<!-- Open-source licences of what ships inside Sliptab. The list is generated by
     scripts/licenses.py into licenses.json and loaded only when this screen opens (~0.9 MB). -->
<script lang="ts">
  type Pkg = { name: string; version: string; license: string; url: string; texts: number[] };
  type Data = { packages: Pkg[]; texts: string[] };
  let data: Data | null = $state(null);
  let q = $state("");
  let open: string | null = $state(null);
  $effect(() => {
    void import("./licenses.json").then((m) => (data = m.default as unknown as Data));
  });
  const shown = $derived(
    ((data as Data | null)?.packages ?? []).filter((p: Pkg) => !q || p.name.toLowerCase().includes(q.toLowerCase())),
  );
</script>

<div class="lic">
  <p class="sub">Sliptab is built with these open-source packages. Thank you to their authors.</p>
  <input class="find" placeholder="Search {data?.packages.length ?? ''} packages" bind:value={q} aria-label="Search packages" />
  {#each shown as p (p.name + p.version)}
    {@const key = p.name + p.version}
    <button class="row" class:on={open === key} onclick={() => (open = open === key ? null : key)} aria-expanded={open === key}>
      <span class="name">{p.name} <span class="ver">{p.version}</span></span>
      <span class="id">{p.license}</span>
    </button>
    {#if open === key && data}
      <div class="text">
        {#if p.url}<p class="url">{p.url}</p>{/if}
        {#each p.texts as t}<pre>{data.texts[t]}</pre>{:else}<pre>Licensed under {p.license}.</pre>{/each}
      </div>
    {/if}
  {/each}
</div>

